#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_get_first_n_digits_insufficient_digits_after_leading_zeros(void) {
    /* Path conditions:
     * 1. number != NULL, out_str != NULL, N > 0, out_str_len > 0, num_digits > 0
     * 2. num_digits < out_str_len
     * 3. The while loop runs (leading zeros exist) and reduces start_pos
     * 4. actual_digits = start_pos + 1 (after skipping zeros) is less than num_digits
     * 5. Function returns -1
     */
    uint8_t number[] = {0, 0, 5, 7};  /* Big-endian: index 3 is most significant.
                                       * Number is 5700? Actually digits: [0,0,5,7]
                                       * Most significant non-zero digit is at index 3 (value 7).
                                       * After skipping zeros from the end (index 3->2->1? Wait: start_pos = N-1 = 3.
                                       * While loop: start_pos > 0 && number[start_pos] == 0.
                                       * number[3] = 7 != 0, so loop exits immediately.
                                       * actual_digits = start_pos + 1 = 4.
                                       * That doesn't trigger the insufficient digits path.
                                       * Need leading zeros at the most significant positions.
                                       * Let's set number = {0, 0, 0, 1} (big-endian, so number is 1000? Actually digits: [0,0,0,1] -> value 1? Wait representation: highest index is most significant.
                                       * So number[3]=1 (most significant), number[2]=0, number[1]=0, number[0]=0.
                                       * That's 1000? Actually digit array: positions 3,2,1,0 -> digits 1,0,0,0 -> number 1000.
                                       * No leading zeros because the most significant digit is 1.
                                       * We need leading zeros: most significant digits are zero.
                                       * Example: number = {0, 0, 0, 0}? That's all zeros, but while loop will go until start_pos=0, actual_digits=1 (since start_pos becomes 0).
                                       * But then number[0] is 0, so actual_digits is 1 (the zero digit).
                                       * Let's have number = {9, 0, 0, 0} (big-endian: index 3 is most significant = 9? Wait: highest index is most significant.
                                       * So number[3]=9, number[2]=0, number[1]=0, number[0]=0 -> digits 9,0,0,0 -> number 9000.
                                       * Again no leading zeros.
       We need leading zeros at the most significant end. That means the highest indices should be zero.
       Example: number = {5, 0, 0, 0} where N=4. Indices: 3,2,1,0.
       Set number[3]=0, number[2]=0, number[1]=0, number[0]=5.
       That's digits: 0,0,0,5 -> number is 5 (with three leading zeros).
       While loop: start_pos = 3.
       number[3]=0 -> start_pos becomes 2.
       number[2]=0 -> start_pos becomes 1.
       number[1]=0 -> start_pos becomes 0.
       number[0]=5 !=0 -> loop stops.
       actual_digits = start_pos + 1 = 1.
       Now if we request num_digits=2, we get num_digits > actual_digits -> return -1.
    */
    uint8_t N = 4;
    uint8_t number[4] = {5, 0, 0, 0}; /* Big-endian: most significant digit at index 3 is 0, next 0, next 0, least significant is 5.
                                         So the number is 5 with three leading zeros. */
    uint8_t num_digits = 2;           /* Request 2 digits, but only 1 non-zero digit exists after skipping zeros. */
    size_t out_str_len = 10;          /* Larger than num_digits to pass second check. */
    char out_str[10];

    int result = get_first_n_digits(number, N, num_digits, out_str, out_str_len);

    TEST_ASSERT_EQUAL_INT(-1, result);
    /* No cleanup needed for stack arrays. */
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_get_first_n_digits_insufficient_digits_after_leading_zeros);
    return UNITY_END();
}

